import { defineOnceTool } from "agevex";
import { z } from "zod";

export const CONTINUE_BUDGET_LIMITS = { minChars: 1, reasonChars: 2000 } as const;
export const CONSENT_LIMITS = { approvalIdBytes: 512, cleanupBatch: 128 } as const;
export const continueInput = z.strictObject({
  reason: z
    .string()
    .trim()
    .min(CONTINUE_BUDGET_LIMITS.minChars)
    .max(CONTINUE_BUDGET_LIMITS.reasonChars),
});

/**
 * Model-side half: ask the user for explicit spending consent.
 *
 * ROOT ONLY. Register this tool on root agents only. Budgets, stops and the
 * resume below are all keyed to the root thread's run. If a delegated child
 * calls it anyway, the tool returns the typed `{ status: "denied", code:
 * "ROOT_ONLY" }` when it would execute. Core evaluates `needsApproval` without
 * the ToolContext (`context` is undefined there), so the child's approval
 * request cannot be suppressed before the user is asked; a user approval on a
 * child thread is harmless because the tool never records or reports consent.
 *
 * This only requests consent. It neither changes a budget nor bypasses core's
 * run limits. The native approval (answered through core `respond`) is the
 * consent record; denial never executes the tool. The host applies its own
 * budget policy afterwards (see `resumeAfterBudgetStop`).
 */
export function createContinueBudgetTool() {
  const approval = defineOnceTool({
    name: "continue_budget",
    input: continueInput,
    run: (input, tc) => {
      tc.signal.throwIfAborted();
      // A budget stop and its resume belong to the root thread's run. A child's
      // consent could never be spent, so refuse instead of reporting approval.
      if (tc.threadId !== tc.rootThreadId) return { status: "denied", code: "ROOT_ONLY" };
      return { approved: true, reason: input.reason };
    },
  });
  approval.description =
    "Ask the user for explicit permission to spend more before the budget runs out. Approval is consent only; the host changes its budget policy separately.";
  approval.needsApproval = true;
  return approval;
}

/** The receipt shape core's `send` returns, reduced to what this flow reads. */
export type SendReceipt =
  | { status: "accepted" | "duplicate"; threadId: string }
  | { status: "rejected"; code: string };

/** Model-facing consent statement placed at the start of the fresh request. */
export const CONSENT_TEXT = "The user approved continuing beyond the budget.";

export type ResumeAfterBudgetStop<Receipt extends SendReceipt> = {
  threadId: string;
  /** The `continue_budget` approval the user answered on this thread. */
  approvalId: string;
  /** Optional extra instruction appended to the consent statement. */
  instruction?: string;
  /** Spend the host's recorded consent (see `continueBudgetState.consume`): true
   * exactly once, only for this owner, thread, approval and stopped run. The helper
   * never calls `respond`, so a pending approval can never be approved on the
   * user's behalf. Must fail closed: anything else is `false`. */
  consumeConsent: (args: {
    threadId: string;
    approvalId: string;
    runId: string;
  }) => Promise<boolean>;
  /** Core `activity`; its `runId` is the id your budget slot received. */
  activity: () => Promise<{ errorCode: string | null; runId?: string | null }>;
  /** Host budget policy write. Runs in the same transaction as cancel and send. */
  raiseBudget: () => Promise<unknown>;
  /** Core `cancel` for the stopped thread. */
  cancel: () => Promise<unknown>;
  /** Core `send` with the supplied `text` and `requestKey`. */
  send: (args: { text: string; requestKey: string }) => Promise<Receipt>;
};

/**
 * Host-side half: continue a run that core stopped with `BUDGET_EXCEEDED`.
 *
 * Core never resumes a stopped run, because the step that tripped the budget may
 * have been paid for with an unknown outcome. The only supported path is:
 *   1. explicit, single-use spending consent recorded by the host's approve action,
 *   2. the host updates its budget policy,
 *   3. cancel the stopped run (clears its recovery state and discards its notes),
 *   4. send a fresh request (a new run with its own run id).
 *
 * ATOMICITY. Call this inside ONE host mutation, with every callback made through
 * `ctx.runQuery`/`ctx.runMutation` (nested Convex calls share the caller's
 * transaction). The stop check, budget write, cancel and send then commit or roll
 * back together. Two overlapping resumes cannot both pass the stop check: the
 * loser either conflicts (OCC) and retries into `not-stopped`, or runs after the
 * winner and sees `not-stopped`. Without this, a second resume that checked the
 * stop before the first committed would cancel the fresh run the first one sent.
 *
 * REQUEST KEY. `after-budget:<threadId>:<stoppedRunId>` is unique per stop, so
 * the same thread can be stopped and resumed any number of times. A `duplicate`
 * or `rejected` receipt is never a success: `send` throws, which rolls back the
 * consent spend, the budget raise and the cancel, leaving the run resumable.
 *
 * MODEL VIEW. Cancel settles the approval call the model made as an
 * `execution-denied` tool result, because core never executes a call whose slice
 * was stopped. The fresh request therefore states the consent explicitly
 * (`CONSENT_TEXT`), so the model does not read that denial as a refusal.
 */
export async function resumeAfterBudgetStop<Receipt extends SendReceipt>(
  flow: ResumeAfterBudgetStop<Receipt>,
): Promise<
  | { status: "no-consent" }
  | { status: "not-stopped" }
  | { status: "resumed"; receipt: Exclude<Receipt, { status: "rejected" | "duplicate" }> }
> {
  const { errorCode, runId } = await flow.activity();
  if (errorCode !== "BUDGET_EXCEEDED" || !runId) return { status: "not-stopped" };
  let approved = false;
  try {
    approved = await flow.consumeConsent({
      threadId: flow.threadId,
      approvalId: flow.approvalId,
      runId,
    });
  } catch {
    // Fail closed: an unknown, foreign or unindexable approval is not consent.
  }
  if (!approved) return { status: "no-consent" };
  await flow.raiseBudget();
  await flow.cancel();
  const receipt = await flow.send({
    text: flow.instruction ? `${CONSENT_TEXT} ${flow.instruction}` : CONSENT_TEXT,
    requestKey: `after-budget:${flow.threadId}:${runId}`,
  });
  // Throwing (not returning) is what rolls back the consent spend, the raise and
  // the cancel. A duplicate means this stop's key was already used for another
  // request, so no fresh run was admitted by this call.
  if (receipt.status === "rejected") throw new Error(receipt.code);
  if (receipt.status === "duplicate") throw new Error("DUPLICATE_RESUME");
  return { status: "resumed", receipt: receipt as Exclude<Receipt, { status: "rejected" | "duplicate" }> };
}

import { defineSchema, defineTable, type DataModelFromSchemaDefinition } from "convex/server";
import { v } from "convex/values";

/**
 * Merge into the host schema. One row records that an owner explicitly approved
 * one `continue_budget` approval on one thread. Core keeps approval decisions
 * inside the native Agent transcript and exposes no read-only "was it approved"
 * query, and reading the transcript to decide anything is not allowed, so the
 * host's approve action records the consent here in the same transaction as the
 * core `respond` call. The row is single-use and bound to the run that was
 * active when the user approved (`activity.runId`): `consume` marks it `spent`
 * only for the stop of that exact run. A spent row is kept (not deleted) so a
 * replayed approve cannot re-create consent: core `respond` replays for
 * LIMITS.receiptRetentionMs (7 days) without re-checking pending state. Every field is read by `consume`.
 */
export const consentTables = {
  agevexBudgetConsents: defineTable({
    subject: v.string(),
    threadId: v.string(),
    approvalId: v.string(),
    runId: v.string(),
    spent: v.boolean(),
  }).index("by_consent", ["subject", "threadId", "approvalId"])
    // Cleanup by owner thread and age: implicit _creationTime follows the fields.
    .index("by_thread", ["subject", "threadId"]),
};
const schema = defineSchema(consentTables);
export type ConsentDataModel = DataModelFromSchemaDefinition<typeof schema>;

import {
  internalMutationGeneric,
  internalQueryGeneric,
  type MutationBuilder,
  type QueryBuilder,
} from "convex/server";
import { LIMITS } from "agevex";
import { v } from "convex/values";
import { CONSENT_LIMITS } from "./continueBudget.js";
import type { ConsentDataModel } from "./continueBudgetSchema.js";

const query = internalQueryGeneric as QueryBuilder<ConsentDataModel, "internal">;
const mutation = internalMutationGeneric as MutationBuilder<ConsentDataModel, "internal">;
const consent = {
  subject: v.string(),
  threadId: v.string(),
  approvalId: v.string(),
  runId: v.string(),
};

// Index fields are limited to 1 KiB each, and the approval id is chosen by the
// model provider. Reject what cannot be indexed instead of truncating it: a
// truncated id could make two approvals look like one consent.
const checkId = (approvalId: string) => {
  if (
    !approvalId ||
    new TextEncoder().encode(approvalId).byteLength > CONSENT_LIMITS.approvalIdBytes
  )
    throw new Error("INVALID_APPROVAL_ID");
};

/**
 * Record explicit consent. Call it from the host mutation that ALSO calls core
 * `respond({ approved: true })`, with the thread's current `activity.runId`, so
 * both commit or neither does. The run id binds the consent to the run that was
 * active when the user approved: an approval from one run can never unlock the
 * stop of another. Re-recording the same approval keeps the first row, spent or not: core
 * `respond` replays its saved result for LIMITS.receiptRetentionMs (7 days)
 * without re-checking that the approval is still pending, so a double-click
 * after a resume would otherwise insert a fresh, unspent row for the new run.
 * subject/threadId/runId are core facts (<= 128 UTF-8 bytes); a row is < 2 KiB,
 * and unique() reads at most two rows (convex/src/server/impl/query_impl.ts:334-343).
 */
export const record = mutation({
  args: consent,
  returns: v.null(),
  handler: async (ctx, args) => {
    checkId(args.approvalId);
    const row = await ctx.db
      .query("agevexBudgetConsents")
      .withIndex("by_consent", (q) =>
        q.eq("subject", args.subject).eq("threadId", args.threadId).eq("approvalId", args.approvalId),
      )
      .unique();
    // A spent row also blocks re-recording: the first row always wins.
    if (!row) await ctx.db.insert("agevexBudgetConsents", { ...args, spent: false });
    return null;
  },
});

/**
 * Spend the consent: true exactly once, and only for this owner, thread,
 * approval AND the stopped run it was recorded for. Call it inside the resume
 * transaction (`resumeAfterBudgetStop` does): marking the row spent commits with
 * the budget raise, cancel and fresh send, and rolls back with them if any step
 * fails. A mismatching run leaves the row untouched, so it stays usable for its
 * own run. Single-use matters because one approval must not authorize every
 * later stop; the row is kept as `spent` (see `record`).
 */
export const consume = mutation({
  args: consent,
  returns: v.boolean(),
  handler: async (ctx, args) => {
    checkId(args.approvalId);
    const row = await ctx.db
      .query("agevexBudgetConsents")
      .withIndex("by_consent", (q) =>
        q.eq("subject", args.subject).eq("threadId", args.threadId).eq("approvalId", args.approvalId),
      )
      .unique();
    if (!row || row.spent || row.runId !== args.runId) return false;
    await ctx.db.patch("agevexBudgetConsents", row._id, { spent: true });
    return true;
  },
});

/**
 * Bounded host cleanup for one deleted thread. Spent rows are what block a
 * replayed approve, and core `respond` can replay for LIMITS.receiptRetentionMs
 * (7 days, exported by agevex), so a row younger than that is never deleted.
 * Deletes at most CONSENT_LIMITS.cleanupBatch rows (< 2 KiB each, < 256 KiB) of
 * that thread created before the cutoff, reading through the by_thread index's
 * _creationTime range so the read is bounded by the batch, and reports
 * `done: false` when more remain. Nothing reschedules itself.
 */
export const cleanup = mutation({
  args: { subject: v.string(), threadId: v.string() },
  returns: v.object({ deleted: v.number(), done: v.boolean() }),
  handler: async (ctx, args) => {
    const cutoff = Date.now() - LIMITS.receiptRetentionMs;
    const rows = await ctx.db
      .query("agevexBudgetConsents")
      .withIndex("by_thread", (q) =>
        q
          .eq("subject", args.subject)
          .eq("threadId", args.threadId)
          .lt("_creationTime", cutoff),
      )
      .take(CONSENT_LIMITS.cleanupBatch + 1);
    const batch = rows.slice(0, CONSENT_LIMITS.cleanupBatch);
    for (const row of batch) await ctx.db.delete("agevexBudgetConsents", row._id);
    return { deleted: batch.length, done: rows.length <= CONSENT_LIMITS.cleanupBatch };
  },
});
